// Parse JSON output from csv_parser.py — always non-blocking.
// csv_parser.py outputs [] on any error or missing file, so exitCode
// check is a safety net only.
const result = $input.first().json;
const exitCode = result.exitCode ?? 0;
const stdout = (result.stdout ?? '').trim();

if (exitCode !== 0) {
  console.log('[Read: Indeed CSV] csv_parser.py exit ' + exitCode + ' — treating as empty result');
  return [{ json: { offers: [], source: 'indeed', count: 0 } }];
}

let offers = [];
try {
  offers = JSON.parse(stdout || '[]');
  if (!Array.isArray(offers)) offers = [];
} catch (err) {
  console.log('[Parse: Indeed Offers] Failed to parse CSV output: ' + stdout.slice(0, 200) + ' — returning []');
  offers = [];
}

console.log('[Parse: Indeed Offers] Loaded ' + offers.length + ' Indeed offers from CSV');
return [{ json: { offers: offers, source: 'indeed', count: offers.length } }];

// Merge Indeed (CSV) + LinkedIn (workflow) — dedup by URL intra-merge, cap 100.
const INDEED_CAP = 60;
const LINKEDIN_CAP = 40;
const GLOBAL_CAP = 100;

// Indeed offers from Parse: Indeed Offers node (earlier in chain)
const indeedOffers = ($('Parse: Indeed Offers').first().json.offers || []).slice(0, INDEED_CAP);

// LinkedIn offers — each $input item is one offer from Execute Workflow: LinkedIn Scan
const linkedinOffers = $input.all()
  .map(item => item.json)
  .filter(o => o && o.url)
  .slice(0, LINKEDIN_CAP);

function normalizeUrl(url) {
  return (url || '').split('?')[0].split('#')[0];
}

const seen = new Set();
const merged = [];

for (const offer of indeedOffers) {
  const key = normalizeUrl(offer.url);
  if (key && !seen.has(key)) {
    seen.add(key);
    merged.push({
      url: offer.url || '',
      title: offer.title || '',
      company: offer.company || '',
      location: offer.location || '',
      description: offer.description || '',
      job_type: offer.job_type || '',
      date_posted: offer.date_posted || offer.date_scanned || '',
      source: 'indeed',
      match_rate: offer.match_rate || null,
      skills_found: offer.skills_found || null,
      job_id: offer.job_id || null,
    });
  }
}

for (const offer of linkedinOffers) {
  const key = normalizeUrl(offer.url);
  if (key && !seen.has(key)) {
    seen.add(key);
    merged.push({
      url: offer.url || '',
      title: offer.title || '',
      company: offer.company || '',
      location: offer.location || '',
      description: offer.description || '',
      job_type: offer.job_type || '',
      date_posted: offer.date_posted || '',
      source: 'linkedin',
      match_rate: null,
      skills_found: null,
    });
  }
}

const capped = merged.slice(0, GLOBAL_CAP);
console.log('[Merge] indeed=' + indeedOffers.length + ' linkedin=' + linkedinOffers.length + ' → merged=' + capped.length);

const scanDate = new Date().toISOString().slice(0, 10);
return [{ json: { offers: capped, count: capped.length, scanDate, source: 'merged' } }];

// Format scan_date as dd.mm.yyyy and extract offers for dedup
const scanResult = $input.first().json.scan_result || $input.first().json;
const offers = scanResult.offers || [];

let scanDate;
try {
  const d = new Date(scanResult.scanDate);
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yyyy = d.getFullYear();
  scanDate = `${dd}.${mm}.${yyyy}`;
} catch (_) {
  const now = new Date();
  scanDate = `${String(now.getDate()).padStart(2,'0')}.${String(now.getMonth()+1).padStart(2,'0')}.${now.getFullYear()}`;
}

const payloadStr = JSON.stringify({ offers, scan_date: scanDate });
return [{
  json: Object.assign({ scan_date: scanDate, offers_count: offers.length }, { payload_bytes: payloadStr.length }),
  binary: { data: { data: Buffer.from(payloadStr).toString('base64'), mimeType: 'application/json', fileName: 'payload.json' } }
}];

// Parse /dedup stdout, split new_offers LinkedIn vs Indeed, prepare /layer1 payload.
const out = $input.first().json.stdout || '{}';
let dedupResult;
try { dedupResult = JSON.parse(out); } catch (e) { dedupResult = {}; }
const newOffers = dedupResult.new_offers || [];
const scanDate = dedupResult.scan_date || '';

const linkedinOffers = newOffers.filter(o => o.source === 'linkedin');
const indeedOffers = newOffers.filter(o => o.source !== 'linkedin');

console.log('[Filter] new=' + newOffers.length + ' linkedin=' + linkedinOffers.length + ' indeed=' + indeedOffers.length);

const payloadStr = JSON.stringify({ offers: linkedinOffers, scan_date: scanDate });
return [{
  json: Object.assign({ linkedin_offers: linkedinOffers, indeed_offers: indeedOffers, scan_date: scanDate }, { payload_bytes: payloadStr.length }),
  binary: { data: { data: Buffer.from(payloadStr).toString('base64'), mimeType: 'application/json', fileName: 'payload.json' } }
}];

// Merge Indeed qualified (match_rate from CSV) + LinkedIn high_match (from Layer2).
// Normalise LinkedIn match_rate from 0-1 fraction to percentage string.
// Compute job_id for LinkedIn via SHA-256[:16] of normalised URL.
const crypto = require('crypto');

function normalizeUrl(url) {
  try {
    const u = new URL(url || '');
    u.search = '';
    u.hash = '';
    return u.toString();
  } catch (e) { return url || ''; }
}

function computeJobId(url) {
  return crypto.createHash('sha256').update(normalizeUrl(url)).digest('hex').slice(0, 16);
}

function toIsoDate(ddmmyyyy) {
  const parts = (ddmmyyyy || '').split('.');
  if (parts.length === 3) return parts[2] + '-' + parts[1] + '-' + parts[0];
  return ddmmyyyy || '';
}

const filterData = $('Filter: Extract LinkedIn').first().json;
const indeedOffers = filterData.indeed_offers || [];
const scanDate = filterData.scan_date || '';
const scanDateIso = toIsoDate(scanDate);

// LinkedIn high_match from Layer2 response (match_rate is 0-1 fraction)
let l2;
try { l2 = JSON.parse($json.stdout || '{}'); } catch (e) { l2 = {}; }
const linkedinHighMatch = l2.high_match || [];

// Indeed: keep offers where match_rate (string percentage) >= 60.0
const qualifiedIndeed = indeedOffers
  .filter(o => parseFloat(o.match_rate || '0') >= 60.0)
  .map(o => ({
    job_id: o.job_id || computeJobId(o.url || ''),
    date_scanned: scanDateIso,
    title: o.title || '',
    company: o.company || '',
    location: o.location || '',
    remote: o.remote || '',
    url: o.url || '',
    source: 'indeed',
    match_rate: o.match_rate || '0',
    skills_found: o.skills_found || '',
    description: o.description || '',
    status: 'new',
  }));

// LinkedIn: convert match_rate 0-1 → percentage string, compute job_id
const qualifiedLinkedin = linkedinHighMatch.map(o => ({
  job_id: computeJobId(o.url || ''),
  date_scanned: scanDateIso,
  title: o.title || '',
  company: o.company || '',
  location: o.location || '',
  remote: o.job_type || '',
  url: o.url || '',
  source: 'linkedin',
  match_rate: (parseFloat(o.match_rate || '0') * 100).toFixed(1),
  skills_found: Array.isArray(o.skills_found) ? o.skills_found.join(',') : (o.skills_found || ''),
  description: o.description || '',
  status: 'new',
}));

// Indeed first (already scored), LinkedIn appended
const newMatches = [...qualifiedIndeed, ...qualifiedLinkedin];

console.log('[Qualify] indeed=' + qualifiedIndeed.length + ' linkedin=' + qualifiedLinkedin.length + ' total=' + newMatches.length);
const payloadStr = JSON.stringify({ new_matches: newMatches });
return [{
  json: Object.assign({ new_matches_count: newMatches.length }, { payload_bytes: payloadStr.length }),
  binary: { data: { data: Buffer.from(payloadStr).toString('base64'), mimeType: 'application/json', fileName: 'payload.json' } }
}];

// Parse /layer1 stdout and prepare /layer2 payload (threshold 0.6).
const out = $input.first().json.stdout || '{}';
let l1;
try { l1 = JSON.parse(out); } catch (e) { l1 = {}; }
const passed = l1.passed || [];
const scanDate = $('Filter: Extract LinkedIn').first().json.scan_date || '';
console.log('[Layer1] passed=' + passed.length + ' rejected=' + ((l1.rejected || []).length));
const payloadStr = JSON.stringify({ offers: passed, scan_date: scanDate, threshold: 0.6 });
return [{
  json: Object.assign({ passed_count: passed.length }, { payload_bytes: payloadStr.length }),
  binary: { data: { data: Buffer.from(payloadStr).toString('base64'), mimeType: 'application/json', fileName: 'payload.json' } }
}];
